import { DomainError } from "../domain/domain-error";
import { OrderRepository } from "../domain/order-repository";
import { isOrderStatus } from "../domain/order-status";
import { OrderDto } from "./order-dto";
import { toOrderDto } from "./order-mapper";

export class AdvanceOrderUseCase {
  constructor(private readonly orders: OrderRepository) {}

  execute(orderId: string, targetStatus: unknown): OrderDto {
    if (!isOrderStatus(targetStatus)) {
      throw new DomainError("VALIDATION", "Unknown order status");
    }
    const order = this.orders.findById(orderId);
    if (!order) {
      throw new DomainError("NOT_FOUND", `Order ${orderId} not found`);
    }
    order.advanceTo(targetStatus);
    this.orders.save(order);
    return toOrderDto(order);
  }
}

=====SOURCE-END=====

